SELECT * FROM ( SELECT A.AL_ID AS ${_iq_}id${_iq_}, A.AL_OP AS ${_iq_}op${_iq_}, A.AL_USER AS ${_iq_}user${_iq_}, A.AL_TARGET AS ${_iq_}target${_iq_}, A.AL_IP AS ${_iq_}ip${_iq_}, A.AL_RESULT AS ${_iq_}result${_iq_}, A.AL_TIME AS ${_iq_}createTime${_iq_} FROM DATAGEAR_AUDIT_LOG A WHERE 1 = 1
AND A.AL_OP = #{op}
ORDER BY A.AL_TIME DESC ) T
